redis-set-algebra.solution:
class SetStore:
    def __init__(self):
        self.sets = {}

    def _get(self, key):
        return self.sets.get(key, set())

    def sadd(self, key, members):
        s = self.sets.setdefault(key, set())
        before = len(s)
        s.update(members)
        return len(s) - before

    def srem(self, key, members):
        s = self._get(key)
        before = len(s)
        s.difference_update(members)
        return before - len(s)

    def sismember(self, key, member):
        return int(member in self._get(key))

    def scard(self, key):
        return len(self._get(key))

    def sinter(self, keys):
        out = set(self._get(keys[0]))
        for k in keys[1:]:
            out &= self._get(k)
        return sorted(out)

    def sunion(self, keys):
        out = set()
        for k in keys:
            out |= self._get(k)
        return sorted(out)

    def sdiff(self, keys):
        out = set(self._get(keys[0]))
        for k in keys[1:]:
            out -= self._get(k)
        return sorted(out)

