redis-lfu-cache.solution:
class LFUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.val, self.freq = {}, {}
        self.groups = collections.defaultdict(collections.OrderedDict)   # count -> keys, oldest first
        self.min_freq = 0

    def _touch(self, key):
        f = self.freq[key]
        del self.groups[f][key]
        if not self.groups[f]:
            del self.groups[f]
            if self.min_freq == f:
                self.min_freq = f + 1
        self.freq[key] = f + 1
        self.groups[f + 1][key] = True

    def get(self, key):
        if key not in self.val:
            return -1
        self._touch(key)
        return self.val[key]

    def put(self, key, value):
        if self.cap == 0:
            return None
        if key in self.val:
            self.val[key] = value
            self._touch(key)
            return None
        if len(self.val) >= self.cap:
            victim, _ = self.groups[self.min_freq].popitem(last=False)
            if not self.groups[self.min_freq]:
                del self.groups[self.min_freq]
            del self.val[victim]
            del self.freq[victim]
        self.val[key], self.freq[key] = value, 1
        self.groups[1][key] = True
        self.min_freq = 1

