    def __init__(self, limit, window):
        self.limit, self.window = limit, window
        self.log = collections.defaultdict(collections.deque)

    def allow(self, user, now):
        q = self.log[user]
        while q and q[0] <= now - self.window:
            q.popleft()
        if len(q) >= self.limit:
            return False
        q.append(now)
        return True

